void tiles_authority(const GameAssets& a) {
  const auto l=tiles_layout(a.version);
  const std::array<std::uint8_t,11> setup{0xe2,0x20,0xa9,1,0x8d,std::uint8_t(l.upload),std::uint8_t(l.upload>>8),0x22,std::uint8_t(l.entry),std::uint8_t(l.entry>>8),0xc2};
  meter_bytes(a,l.setup,setup);
  const std::array<std::uint8_t,19> cold{0xa0,std::uint8_t(l.bg),std::uint8_t(l.bg>>8),0xa2,0x80,3,0x80,9,0xa9,0,0,0x99,0,0,0xc8,0xc8,0xca,0xd0,0xf5};
  meter_bytes(a,0xc20171,cold);
  if(a.version==GameVersion::US)meter_bytes(a,0xc213ac,tiles_us_0);
  if(a.version==GameVersion::US)meter_bytes(a,0xc20d3f,tiles_us_1);
  if(a.version==GameVersion::US)meter_bytes(a,0xc090ff,tiles_us_2);
  if(a.version==GameVersion::US)meter_bytes(a,0xc09231,tiles_us_3);
  if(a.version==GameVersion::US)meter_bytes(a,0xc09251,tiles_us_4);
  if(a.version==GameVersion::JP)meter_bytes(a,0xc2124c,tiles_jp_0);
  if(a.version==GameVersion::JP)meter_bytes(a,0xc20bd0,tiles_jp_1);
  if(a.version==GameVersion::JP)meter_bytes(a,0xc090e1,tiles_jp_2);
  if(a.version==GameVersion::JP)meter_bytes(a,0xc09213,tiles_jp_3);
  if(a.version==GameVersion::JP)meter_bytes(a,0xc09233,tiles_jp_4);
}
SourceMeterTilesContext tiles_context(bool setup=false,unsigned flags=4) {
  return {true,true,true,setup?SourceMeterTilesBoundary::WindowSetup:SourceMeterTilesBoundary::HelperEntry,
    std::uint8_t(setup?0xc1:0xc2),0xc1,0x7e,std::uint8_t(flags),0x1e00,std::uint16_t(setup?0x1fff:0x1ffc),0x1234,0x4567,0x89ab};
}
struct TilesOriginal:MeterOriginal {
  std::bitset<896> changed_bg;
  explicit TilesOriginal(const GameAssets&a,bool fast):MeterOriginal(a,fast) {
    tiles_authority(a);const auto l=tiles_layout(a.version);
    SnesBus pre(a.image,a.version);MainCpu65816 producer(pre);producer.set_runtime(MainCpuRuntime::Legacy);
    producer.emulation_mode=false;producer.status_register=4;producer.data_bank=0x7e;producer.direct_page=0x1e00;
    for(unsigned i=0;i<2048;++i)pre.work_ram[l.bg+i]=std::uint8_t(i*53+0xa7);
    producer.program_counter=0xc20171;unsigned atoms{};
    while(producer.program_counter!=0xc20184&&atoms<6000){producer.step_instruction();++atoms;}
    require(atoms==5380&&producer.program_counter==0xc20184,"Original genuine896word BG2 cold producer did not return");
    for(unsigned i=0;i<2048;++i){require(pre.work_ram[l.bg+i]==(i<1792?0:std::uint8_t(i*53+0xa7)),"Original cold producer altered its retained tail");bus.work_ram[l.bg+i]=pre.work_ram[l.bg+i];}
  }
  unsigned tiles_return()const{return tiles_layout(bus.game_version()).call+4;}
  void audit_tiles() {
    audit();cpu.observe_memory_write=[this](unsigned address,std::uint8_t value) {
      const unsigned bank=address>>16,lo=address&65535;
      if((bank&0x40)==0&&lo==0x420b){require(value==1,"Meter artwork/default NMI started an unowned DMA");
        const unsigned count=bus.read_byte(0x4305)|unsigned(bus.read_byte(0x4306))<<8;require(count==544,"Meter artwork/default NMI lost actual OAM DMA extent");
        dma_debt+=16+std::uint64_t(count)*8;dma_access=true;}
      if(bank==0x7e||((bank&0x40)==0&&lo<0x2000))stores.push_back({instruction_entry,lo,value,bus.master_clocks()});
      const auto bg=tiles_layout(bus.game_version()).bg;
      if(bank==0x7e&&lo>=bg&&lo<bg+1792)changed_bg.set((lo-bg)/2);
    };
  }
  void drain_tiles() {
    while(bus.take_nmi()){
      const unsigned pc=cpu.program_counter,stack=cpu.stack_pointer;interrupted_sites.insert(pc);
      const auto image=bus.cartridge_image();require(image[0xffea]==0x47&&image[0xffeb]==0x81&&image[0x8147]==0x5c&&image[0x8148]==0x70&&image[0x8149]==0x81&&image[0x814a]==0xc0,"Original meter artwork NMI vector differs");
      instruction_entry=0xffffffff;cpu.service_interrupt(true);++interrupts;bool done{};
      for(unsigned i=0;i<2000;++i){if(cpu.program_counter==pc&&cpu.stack_pointer==stack){done=true;break;}step_meter();}
      require(done,"Original NMI lost the literal artwork caller/register frame");
    }
  }
  void instruction_tiles(){drain_tiles();require(cpu.program_counter!=tiles_return(),"Original artwork ran into unowned WindowTick suffix");step_meter();++foreground;drain_tiles();}
};
struct TilesNative {
  // BG2 outlives the actual WindowHost and every Scene borrower.
  std::unique_ptr<cutscenes::DisplayState> bg=std::make_unique<cutscenes::DisplayState>();
  MeterNative host;
  std::unique_ptr<math::SoftwareArithmeticState> scratch=std::make_unique<math::SoftwareArithmeticState>();
  std::unique_ptr<WorldControlState> separate_control;
  bool separate{};
  TilesNative(const GameAssets&a,const session::Content&content,bool fast,bool interrupt=true,bool physical=true)
    :host(a,content,fast,interrupt,physical) {
    const bool us=a.version==GameVersion::US;dialogue::PartyNameInputs names;
    const std::array<std::uint8_t,5> name{std::uint8_t(us?0x71:0x41),std::uint8_t(us?0x72:0x42),std::uint8_t(us?0x73:0x43),std::uint8_t(us?0x74:0x44),0};
    for(auto&member:names.names)member=name;
    host.window_graphics->prepare(names,1);auto art=host.window_graphics->begin_publication(us?dialogue::ArtworkPublication::GeneratedThenCommon:dialogue::ArtworkPublication::All);
    while(art->advance()==dialogue::Progress::Suspended){art->respond();}
    require(art->complete(),"Declared live meter atlas initializer did not finish");
    for(unsigned i=0;i<2048;++i)bg->text_tiles[i]=std::uint8_t(i*53+0xa7);
    host.windows.bind_source_text_tiles(*bg);host.windows.initialize_cold_text_tiles();
    for(unsigned i=0;i<2048;++i)require(bg->text_tiles[i]==(i<1792?0:std::uint8_t(i*53+0xa7)),"Native actual cold producer altered BG2 extent/tail");
  }
  WorldControlState* control(){return separate?separate_control.get():&host.world.control;}
  const WorldControlState* control()const{return separate?separate_control.get():&host.world.control;}
  std::unique_ptr<WorldRuntime::Operation> suspension(SourceMeterTilesContext ctx=tiles_context()) {
    auto op=host.runtime->begin_source_meter_tiles_window_tick(*host.work,ctx,*control(),*scratch);
    for(unsigned i=0;i<100;++i)if(op->advance(1)==dialogue::Progress::Suspended){require(op->service()==SceneService::SourceMeterTiles,"Actual WindowTick did not suspend before source meter artwork");return op;}
    throw std::runtime_error(context+": Source artwork suspension was not reached");
  }
};
